 66 |     /// @notice Allow a user to chose to withdraw vault LP tokens by burning their giant LP tokens. 1 Giant LP == 1 vault LP
 67 |     /// @param _lpTokens List of LP tokens being owned and being withdrawn from the giant pool
 68 |     /// @param _amounts List of amounts of giant LP being burnt in exchange for vault LP
 69 |     function withdrawLPTokens(LPToken[] calldata _lpTokens, uint256[] calldata _amounts) external {
 70 |         uint256 amountOfTokens = _lpTokens.length;
 71 |         require(amountOfTokens > 0, "Empty arrays");
 72 |         require(amountOfTokens == _amounts.length, "Inconsistent array lengths");
 73 | 
 74 |         _onWithdraw(_lpTokens);
 75 | 
 76 |         for (uint256 i; i < amountOfTokens; ++i) {
 77 |             LPToken token = _lpTokens[i];
 78 |             uint256 amount = _amounts[i];
 79 | 
 80 |             _assertUserHasEnoughGiantLPToClaimVaultLP(token, amount);
 81 | 
 82 |             // Burn giant LP from user before sending them an LP token from this pool
 83 |             lpTokenETH.burn(msg.sender, amount);
 84 | 
 85 |             // Giant LP tokens in this pool are 1:1 exchangeable with external savETH vault LP
 86 |             token.transfer(msg.sender, amount);
 87 | 
 88 |             emit LPSwappedForVaultLP(address(token), msg.sender, amount);
 89 |         }
 90 |     }
 91 | 
 92 |     /// @dev Check the msg.sender has enough giant LP to burn and that the pool has enough savETH vault LP
 93 |     function _assertUserHasEnoughGiantLPToClaimVaultLP(LPToken _token, uint256 _amount) internal view {
 94 |         require(_amount >= MIN_STAKING_AMOUNT, "Invalid amount");
 95 |         require(_token.balanceOf(address(this)) >= _amount, "Pool does not own specified LP");
 96 |         require(lpTokenETH.lastInteractedTimestamp(msg.sender) + 1 days < block.timestamp, "Too new");
 97 |     }
